create or replace function public.protect_profile_sensitive_fields() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare v_uid uuid:=auth.uid();v_role text;v_company uuid;v_claims text:=nullif(current_setting('request.jwt.claims',true),'');v_jwt_role text:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),case when v_claims is not null then v_claims::jsonb->>'role' else null end);
begin if v_jwt_role='service_role' then return new;end if;if v_uid is null then raise exception 'Usuario no autenticado';end if;select role,company_id into v_role,v_company from public.profiles where id=v_uid;if v_role='owner' and old.company_id=v_company then return new;end if;if new.company_id is distinct from old.company_id or new.role is distinct from old.role or new.permissions is distinct from old.permissions or new.active is distinct from old.active then raise exception 'No podés modificar tu rol, permisos, comercio o estado';end if;if new.id is distinct from old.id then raise exception 'No podés modificar el identificador del perfil';end if;return new;end;$$;

create or replace function public.can_use_cash_register() returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select case when auth.uid() is null then false when public.current_user_role()='owner' then true else coalesce((select (p.permissions->>'can_open_close_cash')::boolean from public.profiles p where p.id=auth.uid()),public.current_user_role() in('cashier','manager','supervisor')) end $$;
revoke all on function public.can_use_cash_register() from public,anon;grant execute on function public.can_use_cash_register() to authenticated,service_role;
drop policy if exists cash_movements_authorized_select on public.cash_movements;drop policy if exists cash_movements_authorized_insert on public.cash_movements;create policy cash_movements_authorized_select on public.cash_movements for select to authenticated using(company_id=public.current_user_company_id() and public.can_use_cash_register());create policy cash_movements_authorized_insert on public.cash_movements for insert to authenticated with check(company_id=public.current_user_company_id() and public.can_use_cash_register());
